  { json: { id: "DEV-01", monto: 15000, ruta: "Aprobacion_Automatica" } },
  { json: { id: "DEV-02", monto: 25000, ruta: "Revision_Manual" } },
  { json: { id: "DEV-03", monto: 10000, ruta: "Aprobacion_Automatica" } },
  { json: { id: "DEV-04", monto: 5000, ruta: "Rechazo_Plazo" } }
];

let total_dia = 0;
let total_solicitudes = 0;
let aprobadas = 0;
let reporte = " RESUMEN DIARIO DE SOLICITUDES\n\n";

// 1. Recorremos tu tabla para sumar y armar el texto por ruta
for (const item of $input.all()) {
  let ruta = item.json.ruta;
  let cantidad = item.json.count_id;
  let monto = item.json.sum_monto;

  total_dia += monto;
  total_solicitudes += cantidad;

  if (ruta === "Aprobacion_Automatica") {
    aprobadas += cantidad;
  }

  reporte += `- Ruta ${ruta}: ${cantidad} solicitudes ($${monto})\n`;
}

// 2. Calculamos la tasa (fórmula matemática simple)
let tasa = (aprobadas / total_solicitudes) * 100;

// 3. Agregamos los totales globales al mensaje
reporte += `\n MONTO TOTAL DEL DÍA: $${total_dia}`;
reporte += `\n TASA DE APROBACIÓN AUTOMÁTICA: ${tasa}%`;

// 4. Entregamos el paquete final
return { json: { mensaje_final: reporte } };
